318:     private final class Standalone implements J3CollectionExecutor.ProviderAccess {
319:         final Order order;final Supplier<String> cancelled;
320:         ManualProviderRequestCoordinator.CampaignLease lease;
321:         PlaywrightProviderCampaign campaign;
322:         boolean closed,releaseAttempted;
323:         Standalone(Order order,Supplier<String> cancelled) {this.order=order;this.cancelled=cancelled;}
324: 
325:         @Override public ScheduledEventsTransportResponse execute(ScheduledEventsProviderPageRequest request,Runnable dispatch) {
326:             check();
327:             String unavailable=providerUnavailableReason();
328:             if(unavailable!=null) throw new IllegalStateException(unavailable);
329:             if(lease==null) {
330:                 // No SQL transaction spans this bounded wait.
331:                 while(lease==null) {
332:                     check();
333:                     try {lease=coordinator.tryAcquireJ3Campaign(order.id());}
334:                     catch(ManualProviderRequestCoordinator.CoordinationException busy) {
335:                         if(!Instant.now().plusSeconds(130).isBefore(order.deadline())) throw busy;
336:                         try {Thread.sleep(100);} catch(InterruptedException interrupted) {
337:                             Thread.currentThread().interrupt();throw new PlaywrightDispatchCancelledException();
338:                         }
339:                     }
340:                 }
341:             }
342:             if(campaign==null) campaign=factory.open(order.id(),Set.of(SofascoreEndpointType.SCHEDULED_EVENTS));
343:             lease.beginRequest();
344:             var response=campaign.execute(PlaywrightProviderRequest.scheduledEvents(request.date(),request.page()),
345:                     new PlaywrightDispatchAdmission() {
346:                         public void check() {Standalone.this.check();}
347:                         public Permit acquireDispatchPermit() {check();dispatch.run();return ()->{};}
348:                     });
349:             return new ScheduledEventsTransportResponse(request.requestKey(),response.requestedAt(),response.receivedAt(),
350:                     response.httpStatus(),response.contentType().isBlank()?"application/octet-stream":response.contentType(),
351:                     response.latency(),response.payload());
352:         }
353:         private void check() {
354:             if(closed || cancelled.get()!=null || !Instant.now().isBefore(order.deadline()))
355:                 throw new PlaywrightDispatchCancelledException();
356:             if(lease!=null && !guard.isOwned(lease.ownership())) throw new PlaywrightDispatchCancelledException();
357:         }
358:         @Override public void close() {
359:             if(closed) return;
360:             if(campaign!=null) campaign.close();
361:             if(supervisor.activeCampaignId().filter(order.id()::equals).isPresent())
362:                 throw new IllegalStateException("PROVIDER_CLEANUP_UNVERIFIED");
363:             closed=true;
364:         }
365:         void release() {
366:             if(lease==null) return;
367:             try {
368:                 close();
369:                 if(releaseAttempted) lease.retryCloseAfterVerifiedCleanup();
370:                 else {releaseAttempted=true;lease.close();}
371:             } catch(RuntimeException failure) {
372:                 supervisor.stopCampaign(order.id(),Set.of(SofascoreEndpointType.SCHEDULED_EVENTS));
373:                 guard.requireCleanup(lease.ownership(),Instant.now());throw failure;
374:             }
375:         }
376:     }
